/* Types */
export type AboutInfo = {
	version: string,
	/**  Where the index is kept (Advanced only). */
	data_dir: string,
	start_with_windows: boolean,
	/**
	 *  "Start with Windows" was already chosen once (wizard or Settings). The wizard then shows
	 *  the current state and never re-enables autostart behind the user's back (OQ-16).
	 */
	autostart_decided: boolean,
};

/**  Kind of icon the row shows (DS-3). */
export type ActivityIcon = "folder_added" | "folder_removed" | "up_to_date" | "skipped" | "upgraded" | "app" | "request" | "updated" | "moved";

export type ActivityPageView = {
	rows: ActivityRow[],
	/**  Paging key for "Show more" (`None` = no more). */
	next_before_id: number | null,
};

export type ActivityRow = {
	id: number | null,
	/**  ms since the Unix epoch (day headings and the time column are formatted by the UI). */
	ts_ms: number | null,
	icon: ActivityIcon,
	/**  One plain sentence, e.g. "“Documents” is up to date · 2,100 files". */
	text: string,
	/**  The folder the row is about (its name links to the folder detail when it still exists). */
	folder_id: string | null,
	/**  "{k} files skipped in …": the link goes to that folder's skipped list. */
	to_skipped: boolean,
};

/**  Settings → Advanced (02 §2.5): the switches the M2 app can change. */
export type AdvancedView = {
	/**  "Use graphics card": Auto (true, default) or Off. */
	use_graphics_card: boolean,
	/**  Connected apps may ask to add folders (each request needs approval here). Off by default. */
	allow_app_folder_requests: boolean,
	/**
	 *  Connected apps may ask to check a folder for changes now (MCP `sync_folder`). Off by
	 *  default.
	 */
	allow_app_folder_checks: boolean,
	/**  A change applies after Selene Retrieval restarts. */
	restart_needed: boolean,
};

/**
 *  Page 27. `text` is plain text with `[n]` markers that point at `sources[].n`; markers that
 *  don't match a cited source are left as text by the UI.
 */
export type AnswerView = {
	text: string,
	/**  The sources the answer cites, in the order of first citation (the "Sources" list). */
	sources: SourceView[],
	provider_name: string | null,
	model: string | null,
	/**  Extra search rounds used (deeper answers). */
	rounds: number,
	/**  Nothing matched: no provider call was made (page 27 no-match line). */
	no_good_match: boolean,
	no_folders: boolean,
};

/**  Settings → Answers (page 23), shown only once a provider exists. */
export type AnswersView = {
	answers_enabled: boolean,
	/**  Off until the user turns it on (P1.2, U26). */
	deeper_answers: boolean,
	/**  Extra search rounds for deeper answers (Advanced, 1–5). */
	max_rounds: number,
};

export type AppKind = "claude_desktop" | "cursor" | "vs_code" | "other" | "http";

/**  Everything the UI shows about the engine. Pushed whole on every change (`StateChanged`). */
export type AppView = {
	overall: Overall,
	/**  Plain one-liner for the header and the tray tooltip. */
	summary: string,
	folders: FolderView[],
	/**  Set while the background service can't be reached. */
	problem: UiError | null,
	tier: TierView | null,
	/**  Increments whenever the background service restarted and the app re-attached. */
	reconnects: number,
	/**  Notices from the service, e.g. "Some settings were reset" (R-UX19). */
	notices: UiError[],
	/**  A search model change in progress or just finished ([Use it]). */
	model_change: ModelChangeView | null,
	/**  Pending `add_folder` requests from connected apps. */
	approvals: ApprovalView[],
	/**  The restart catch-up is running (Amendment 4.24): the Overview shows the page 03 info row. */
	catching_up: boolean,
	/**  GPU indexing waits while a full-screen app is open (R-UX32); the summary says so. */
	waiting_for_fullscreen: boolean,
	/**  Health of the configured AI provider (pushed `ProviderHealth`). */
	provider_health: ProviderHealthView | null,
	/**  A consent the service asked for that the user hasn't answered yet (page 22). */
	consent_request: ConsentRequest | null,
	/**
	 *  Set when the app was opened for a folder request (`sr-app --approve <id>`, R-UX30): the UI
	 *  brings that card into view and focuses its heading.
	 */
	focus_approval: string | null,
	/**
	 *  M4 (page 03): [Restart now] / [Restart Selene Retrieval] is restarting the background
	 *  service; the shell shows "Restarting the background service…" until it is back.
	 */
	restarting: boolean,
	/**  M4 (page 32): the search index is being moved (pushed `index.move.progress`). */
	index_move: IndexMoveView | null,
	/**  M5 (page 33): what the organisation's policy sets; empty without a policy. */
	policy: PolicyView,
	/**  M5 (R34): the moved search index can't be found; the service waits in its recovery mode. */
	index_missing: IndexMissingView | null,
	/**
	 *  M5 S-04 (R40): the file reader runs with the low-integrity fallback; Settings shows the
	 *  quiet line "File reader running with reduced protection".
	 */
	reduced_protection: boolean,
};

/**  A connected app asks to add a folder (MCP `add_folder`, off by default): the user decides here. */
export type ApprovalView = {
	id: string,
	/**  "Claude", "Cursor", "VS Code" or "An app". */
	client: string,
	path: string,
	/**
	 *  When the request expires, in ms since the Unix epoch (0 = unknown). The card shows
	 *  "Expires in about {m} minutes." once under 5 minutes remain, recomputed on each push.
	 */
	expires_at_ms: number | null,
};

/**
 *  How a provider signs in (provider list `auth_kind`). Account sign-in providers are available
 *  only when they reuse the user's own CLI login ("Claude (sign in)", "Codex (sign in)", M5-C).
 */
export type AuthKind = 
/**  Paste an API key (validated live, kept in Windows Credential Manager). */
"api_key" | 
/**
 *  Signs in with an account: "Claude (sign in)" / "Codex (sign in)" use the local CLI's
 *  login (no key); other account rows are shown disabled.
 */
"oauth" | 
/**  Runs on this computer: an address instead of a key. */
"local";

/**  What a settings change will do, so the UI can confirm **before** saving (page 25). */
export type ChangeImpact = 
/**  Saves at once. */
"none" | 
/**  "This re-reads the folder. Search keeps working meanwhile." */
"reread";

export type ChunkPreset = "balanced" | "small" | "large" | "custom";

/**  Pushed when Claude's config file changes on disk (ours or someone else's write). */
export type ClaudeConfigChanged = ConnectStatus;

export type ClaudeState = "not_installed" | "not_connected" | "connected" | 
/**  Our entry exists but points to an old location: "Reconnect". */
"needs_reconnect" | 
/**  Claude's settings file isn't valid; we won't edit it. Offer the snippet. */
"cant_read";

/**  [Sign in]: what happened. */
export type CliSignInStart = {
	status: CliSignInStatus,
	/**  The tool's sign-in window opened. */
	started: boolean,
};

/**  Where the sign-in stands (the service's `CliSigninState`). */
export type CliSignInState = 
/**  The tool isn't on this computer. */
"not_installed" | 
/**  Installed, not signed in. */
"signed_out" | 
/**  Its sign-in window is open. */
"signing_in" | 
/**  Signed in: Selene Retrieval uses that sign-in. */
"signed_in";

/**  One CLI sign-in provider's state for its card. Never carries a token. */
export type CliSignInStatus = {
	/**  `claudecode` | `codex`. */
	provider: string,
	state: CliSignInState,
	signed_in: boolean,
	/**  The account's email, when the tool reports one (Claude). */
	email: string | null,
	/**  "Max", "Pro", "ChatGPT", … */
	plan: string | null,
	/**  The user's tool: "Claude Code" / "Codex". */
	tool: string,
	/**  The tool's own download page (from the provider list; the only address the card opens). */
	install_url: string | null,
	/**  The status check itself failed (timeout, unreadable answer): "Couldn't check" + [Check again]. */
	check_failed: boolean,
};

/**  The AI apps Selene Retrieval can connect with one click (page 29). */
export type ClientApp = "claude_desktop" | "cursor" | "vs_code";

/**
 *  One app card on Connected apps (page 29). The connection states are the DS-5.5 states, used
 *  for every app (`ClaudeState` is the shared name).
 */
export type ClientStatus = {
	app: ClientApp,
	name: string,
	state: ClaudeState,
	/**  Setup text in this app's own format (OQ-44), with no token (the pipe is user-only). */
	snippet: string,
	/**  The app removed our entry itself (R-UX23; tracked for Claude Desktop). */
	changed_externally: boolean,
	/**  When the app last used Selene Retrieval (ms since the Unix epoch), if the service knows. */
	last_used_ms: number | null,
};

/**  Pushed when any connected app's config changes on disk (page 29 cards; never polled). */
export type ClientsChanged = ClientsView;

/**  Connected apps (page 29): the one-click apps and the "Other app" setup text. */
export type ClientsView = {
	apps: ClientStatus[],
	/**  "Other app": Claude-format setup text with the generic client id. */
	other_snippet: string,
};

export type ConnectResult = {
	status: ConnectStatus,
	/**  Plain next step, e.g. "Restart Claude to finish." */
	message: string,
};

export type ConnectStatus = {
	claude: ClaudeState,
	/**  Copy-paste text for any MCP client (stdio; no token needed). */
	snippet: string,
	/**
	 *  Claude itself rewrote its settings and our entry is gone (R-UX23): the card says
	 *  "Claude's settings were changed and no longer include Selene Retrieval." + Reconnect.
	 */
	changed_externally: boolean,
};

/**
 *  What a provider may receive (02 §2.5 purposes). `answer` and `iterate` are one consent
 *  (OQ-34); `validate_key` and `list_models` are consented by the [Check and save] click itself.
 */
export type ConsentPurpose = 
/**  Questions and matching file text (answers and deeper answers). */
"answer" | 
/**  Your prompt (better prompts). */
"enhance" | 
/**  Search results (remote re-ranking). */
"rerank" | 
/**  The text of your files (remote embeddings): the stronger wording. */
"embed_doc" | 
/**  Your search text (remote embeddings). */
"embed_query";

/**
 *  The service needs a consent the user hasn't given yet (e.g. Claude asked for an answer): the
 *  app shows the consent dialog (page 22) while it is open.
 */
export type ConsentRequest = {
	/**  Provider id (from the provider list). */
	provider: string,
	/**  Display name for the dialog text. */
	provider_name: string,
	purpose: ConsentPurpose,
};

/**  One "Allowed to send" row (page 21). */
export type ConsentRow = {
	purpose: ConsentPurpose,
	allowed: boolean,
};

/**  Whether to show [Create a folder for me], and which folder it already is. */
export type DefaultFolderOffer = {
	/**
	 *  Show [Create a folder for me]: Documents was found, the folder isn't in Selene Retrieval
	 *  yet (nor inside an added folder), and no organisation policy limits where folders go.
	 */
	available: boolean,
	/**
	 *  The default folder is already in Selene Retrieval: its id (its details page says "Anything
	 *  you put here becomes searchable automatically").
	 */
	folder_id: string | null,
	/**  The folder's name ("Selene Retrieval"), for the button's description. */
	name: string,
};

/**  What [Create a folder for me] did. */
export type DefaultFolderResult = {
	/**
	 *  The folder whose details to show: the new folder, or the added folder that already
	 *  contains it (e.g. Documents itself).
	 */
	folder_id: string,
	name: string,
	path: string,
	/**  The folder was made now (`false`: it was already there and is used as it is). */
	created: boolean,
	/**  It was already in Selene Retrieval; nothing was added. */
	already_added: boolean,
	/**  File Explorer was opened on it. */
	opened: boolean,
	/**  It is inside OneDrive (files kept only online there are skipped, with the usual note). */
	in_onedrive: boolean,
};

export type EgressPageView = {
	rows: EgressRowView[],
	next_before_id: number | null,
	/**  Every provider ever used; empty = hide the "Sent to AI providers" card. */
	providers: ProviderChoice[],
};

export type EgressRowView = {
	id: number | null,
	ts_ms: number | null,
	provider_name: string,
	/**  The purpose in plain words (`Purpose::plain()`), e.g. "questions and matching file text". */
	what: string,
	/**  "12 KB". */
	size: string,
	/**  "This app" / "Claude Desktop" / … */
	requested_by: string,
};

/**  Page 28 result. */
export type EnhanceView = {
	/**  The improved prompt (plain text). */
	prompt: string,
	/**  The prompt changed. */
	enhanced: boolean,
	/**  The heuristic fallback wrote it: "Improved without AI this time ({provider} didn't respond)." */
	fallback: boolean,
	provider_name: string | null,
	/**  File names of the context used ("Used context from {n} files"). */
	files: string[],
};

/**  Pre-scan estimate shown in the wizard. */
export type Estimate = {
	files: number,
	/**  True when the count stopped early (very large folder); `files` is then a lower bound. */
	capped: boolean,
	eta_s: number,
	/**  Plain sentence, e.g. "About 2,300 files. This first pass should take about 10 minutes." */
	text: string,
};

export type FieldProblem = {
	field: string,
	text: string,
};

export type FileCountsView = {
	indexed: number,
	pending: number,
	skipped: number,
	/**
	 *  Listed, not read (never counted as skipped): an access grant's files, or those of a folder
	 *  paused by Amendment 17 until the user chooses.
	 */
	listed: number,
};

export type FileTypes = "documents" | "code" | "documents_and_code" | "all_text" | "custom";

/**  Page 25 (status, progress and the state line come live from `AppView.folders`). */
export type FolderDetailView = {
	id: string,
	name: string,
	path: string,
	available: boolean,
	group_id: string,
	group_name: string,
	paused: boolean,
	/**  "Last checked {time}" (ms since the Unix epoch). */
	last_checked_ms: number | null,
	counts: FileCountsView,
	skipped: SkippedRow[],
	skipped_total: number,
	settings: FolderSettingsView,
	/**  Network / no-live-updates note (DS-5.3). */
	watch_note: string | null,
	/**
	 *  M5 (DS-5.3): files skipped because they are stored only in OneDrive. From the service's
	 *  count (`FolderInfo.online_only_skipped`, M5-E); an older service: counted from the skipped rows shown.
	 */
	online_only_skipped: number,
	/**  M5: the service's OneDrive note for this folder (`cloud_note`). */
	cloud_note: string | null,
};

export type FolderNote = {
	kind: FolderNoteKind,
	/**
	 *  Exact text from the service (`sr_sync::watch_note`), e.g. "This folder is on a network
	 *  drive, so changes are picked up every hour."
	 */
	text: string,
};

/**  Kind of the extra note under a folder's status line (DS-5.3). */
export type FolderNoteKind = 
/**  Network drive, or a drive without live updates: changes are picked up on a schedule. */
"network";

/**  One folder's settings (page 25). Labels are the doc comments of `FolderSettings`. */
export type FolderSettingsView = {
	/**  Name shown in the app and to connected apps. Empty = the folder's own name. */
	display_name: string,
	/**  Keep this folder up to date automatically. */
	keep_up_to_date: boolean,
	/**  Which kinds of files to include. */
	file_types_preset: FileTypes,
	/**  Include OneDrive files that are only stored online (downloads them). M5 in the UI. */
	include_online_only: boolean,
	/**  When to re-check the folder (used when "keep up to date" is on). */
	sync_mode: SyncMode,
	/**  Full re-check interval in minutes (5-1440). */
	cadence_min: number,
	/**  When to re-index changed files. */
	reindex_policy: ReindexPolicy,
	/**  Include subfolders. */
	recursive: boolean,
	/**  Extensions to include when the preset is "custom" (without the dot, e.g. "md"). */
	include_extensions: string[],
	/**  Extra glob patterns to exclude. */
	exclude_globs: string[],
	/**  Skip files larger than this many bytes (1 KiB-200 MiB). */
	max_file_bytes: number,
	/**  Chunk size preset. */
	chunk_preset: ChunkPreset,
	/**  Custom chunk size in tokens (64-8192). */
	chunk_size_override: number | null,
	/**  Custom chunk overlap in tokens (0-2048, smaller than the chunk size). */
	chunk_overlap_override: number | null,
	/**  Follow symbolic links (never outside the folder). */
	follow_symlinks: boolean,
};

export type FolderState = "waiting" | "scanning" | "indexing" | "up_to_date" | "up_to_date_with_skips" | "paused" | "unavailable" | "problem" | 
/**  Removed by the user, still being deleted from the index until `PurgeCompleted` (OQ-18). */
"removing" | 
/**  A run stopped before the end (`partial`, OQ-37): search covers what's done. */
"stopped";

export type FolderView = {
	id: string,
	name: string,
	/**  Full path, when known (from `folders.list`); the snapshot carries only names. */
	path: string | null,
	state: FolderState,
	/**  Plain one-liner, e.g. "Indexing 340 of 2,100 files · about 4 minutes left". */
	line: string,
	files_done: number,
	files_total: number,
	files_skipped: number,
	eta_s: number | null,
	/**  Network-drive / no-live-updates note (OQ-38), when the service sends one. */
	note: FolderNote | null,
	/**  Folder group (M4, page 31; Advanced only). `None` from an older service. */
	group_id: string | null,
	/**
	 *  Paused because it was set to only list its files, a mode that was removed (Amendment 17):
	 *  the card asks the user to search its contents (resume) or remove it.
	 */
	was_files_only: boolean,
	/**
	 *  M5 (DS-5.3): files skipped because they are stored only in OneDrive ("Some files are
	 *  stored only in OneDrive and were skipped." + [Include them]). 0 = none or not known.
	 */
	online_only_skipped: number,
	/**  M5: the service's OneDrive note for this folder, when it sends one (`cloud_note`). */
	cloud_note: string | null,
};

export type GroupDeleted = {
	moved_folders: number,
	/**  Apps that now see no folder at all (page 31 notice, fail closed). */
	apps_without_access: string[],
};

export type GroupRow = {
	id: string,
	name: string,
	/**  "My folders": can't be deleted; new folders go here. */
	is_default: boolean,
	folder_ids: string[],
};

export type HitView = {
	line_start: number,
	line_end: number,
	/**  Plain text (≤ 4000 chars); never markup. */
	snippet: string,
	scores: Scores,
};

/**  The opt-in local server (off by default, 127.0.0.1 only, token required). */
export type HttpView = {
	enabled: boolean,
	running: boolean,
	/**  "Address: http://127.0.0.1:{port}" while running. */
	url: string | null,
	/**  Set when it is on but couldn't start (e.g. the port couldn't be opened). */
	problem: UiError | null,
	tools: number,
};

export type IndexLocationView = {
	path: string,
	is_default: boolean,
	/**  "Now: {path} · {size}". */
	size: string,
	free: string,
};

/**
 *  R34: the moved search index can't be found; the service waits in its recovery mode and
 *  starts by itself once the drive is back.
 */
export type IndexMissingView = {
	/**  Where the index should be (the folder the user moved it to). */
	path: string,
	/**  Its drive ("D:"), when it has one. */
	drive: string | null,
	/**  A complete earlier copy [Move the index back] can use; `None` → only [Start fresh]. */
	old_copy: string | null,
	/**  Folders [Start fresh] adds back and reads again. */
	folders_to_restore: number,
	/**  The renderer's title and body for the dedicated code (no action: the screen has its own). */
	error: UiError,
};

/**  Progress of "Move the search index" (page 32). */
export type IndexMoveView = {
	/**  Waiting / copying / verifying (can be cancelled) or switching / cleaning (can't). */
	can_cancel: boolean,
	percent: number,
	/**  "Moving… {done} of {total} GB" (or "Starting Selene Retrieval…" while waiting). */
	line: string,
	from: string,
	to: string,
};

/**  Where the configured provider's key stands. */
export type KeyCheck = 
/**  Checked with the provider and working. */
"working" | 
/**  Saved while offline; it is checked when online ("Saved, not checked yet"). */
"not_checked" | 
/**  The last check failed (`last_error` says why, with one action). */
"failed";

/**  One bundled licence text (`<install dir>\licenses\*.txt`), for "View licences" (page 18). */
export type LicenseText = {
	/**  File name without `.txt`, e.g. "LICENSE-selene-retrieval". */
	name: string,
	text: string,
};

/**  One setting the organisation set (page 33). */
export type ManagedFieldView = {
	/**
	 *  Dotted settings path, or one of M5-E's pseudo paths (`provider.remote`,
	 *  `search.model_downloads`, `folders.allowed_roots`, …).
	 */
	path: string,
	/**  "Managed by your organisation". */
	message: string,
	/**  Plain extra line, e.g. "Allowed: Ollama, OpenAI" or the allowed folder roots. */
	detail: string | null,
};

export type ModelChangeView = {
	step: ModelStep,
	/**  Progress: MB for a download, chunks for the re-index. */
	done: number,
	total: number,
	/**  Plain line, e.g. "Downloading better search… 52 of 208 MB". */
	text: string,
	/**  Set when the change stopped and needs the user (one action). */
	error: UiError | null,
};

/**  One model the provider offers (`list_models`). */
export type ModelOption = {
	id: string,
	name: string,
};

/**
 *  Where a search model change ("Use it") is. Pushed by the service's `model.download.*`,
 *  `reembed.*` and `index.swapped` events (never polled).
 */
export type ModelStep = "downloading" | 
/**  Metered connection: paused until the user picks "Download anyway" (or another network). */
"waiting_for_unmetered" | 
/**  Re-indexing with the new model; search keeps working on the current one. */
"improving" | "done" | "failed";

export type MoveCheckView = {
	/**  [Move] enabled. */
	ok: boolean,
	/**  Where the index will live ("<target>\SeleneRetrieval Index"). */
	index_path: string,
	/**  "New: {path} · {free} free". */
	free: string,
	/**  The one problem in plain words, or `None` ("Enough space"). */
	problem: string | null,
};

/**  Overall state, used for the tray icon and the header line. */
export type Overall = 
/**  Attaching to (or starting) the background service. */
"starting" | "no_folders" | "indexing" | "synced" | 
/**  Something needs the user (folder unavailable, service down). */
"problem";

/**  What the organisation's policy sets. Empty = no policy (the default). */
export type PolicyView = {
	managed: ManagedFieldView[],
};

export type ProviderChoice = {
	id: string,
	name: string,
};

/**  Health of the configured AI provider (`ProviderHealth` event). */
export type ProviderHealthView = "ok" | "degraded" | "down";

/**
 *  One provider from the generated provider list (`selene-providers.json`, synced from Selene by
 *  `xtask sync-providers`). No provider or model name is hard-coded in the app.
 */
export type ProviderOption = {
	id: string,
	name: string,
	auth: AuthKind,
	/**
	 *  False for providers the app can't set up yet: shown, not selectable. "Claude (sign in)" and
	 *  "Codex (sign in)" are available (Amendments 10.2 / 10.3).
	 */
	available: boolean,
	/**
	 *  Why an unavailable provider can't be chosen, from the provider list (e.g.
	 *  `pending_vendor_approval`); `None` when it is available.
	 */
	disabled_reason: string | null,
	/**  Pre-filled address for providers that run on this computer. */
	default_address: string | null,
	/**  Example model, shown only as an "e.g. …" hint; the real list comes from the provider. */
	model_hint: string | null,
	/**
	 *  "Where do I get a key?" (page 21, Amendment 8.3): the provider's own `https://` page, from
	 *  the provider list. `None` = no link is shown.
	 */
	key_url: string | null,
};

/**
 *  Providers & Keys (page 21). The key itself never reaches the UI: only whether one is saved
 *  and its last 4 characters.
 */
export type ProviderStatus = {
	/**  Configured provider id; `None` = no provider (search works without one). */
	provider: string | null,
	provider_name: string | null,
	key_saved: boolean,
	/**  Last 4 characters of the saved key ("" when none, or for a local provider). */
	key_last4: string,
	/**  Address of a provider that runs on this computer. */
	address: string | null,
	check: KeyCheck,
	/**  The last check's error when it failed. */
	last_error: UiError | null,
	/**  Chosen answer model; `None` = automatic (`default_model`). */
	model: string | null,
	/**  The automatically chosen model ("Automatic ({model})"). */
	default_model: string | null,
	models: ModelOption[],
	/**  Remote embeddings are in use (Advanced): the file-text and search-text rows appear. */
	remote_embeddings: boolean,
	/**  Remote re-ranking is in use: the search-results row appears. */
	remote_rerank: boolean,
};

/**  [Move the index back] / [Start fresh] (R34). */
export type RecoverChoice = 
/**  Use the earlier complete copy again (changes since the move are picked up by a re-scan). */
"move_back" | 
/**
 *  An empty index in the usual place; the remembered folders are read again. The missing
 *  copy isn't touched, and neither are the user's files.
 */
"start_fresh";

export type ReindexPolicy = "smart" | "always" | "never";

/**  One result card: a file with its hits, best first. */
export type ResultFile = {
	/**  Absolute path ([Copy path], [Show in folder]). */
	path: string,
	rel_path: string,
	file_name: string,
	folder_id: string,
	folder_name: string,
	hits: HitView[],
};

/**  Result of [Check and save]. */
export type SaveResult = {
	status: ProviderStatus,
	/**  False when the key was saved without checking (offline, "Save without checking"). */
	validated: boolean,
};

/**  "All my folders" (default) or only some folder groups. Unknown groups grant nothing. */
export type ScopeView = { mode: "all" } | { mode: "groups"; group_ids: string[] };

export type Scores = {
	rrf: number | null,
	dense: number | null,
	bm25: number | null,
	rerank: number | null,
};

export type SearchView = {
	files: ResultFile[],
	/**  Chunk-level hits returned (for "Show more results": more may exist when = asked). */
	hits: number,
	asked: number,
	/**  Distinct folders among the results ("{n} results in {m} folders"). */
	folders: number,
	no_folders: boolean,
	/**  "Nothing closely matched …" (R-UX18): `files` is empty on purpose. */
	no_good_match: boolean,
};

export type ServiceClient = {
	client_id: string,
	kind: AppKind,
	name: string,
	scope: ScopeView,
	/**  "Last used {time}" (ms since the Unix epoch). */
	last_used_ms: number | null,
	/**  Live sessions right now. */
	sessions_open: number,
	/**  HTTP tools: shown as "hidden, ends in {last4}". */
	token_last4: string | null,
};

export type ServiceClientsView = {
	clients: ServiceClient[],
	http: HttpView,
};

/**  M4 service pushes: "re-read X" signals and one-off results (`ServiceSignal`). */
export type ServicePush = ServiceSignal;

/**
 *  A pushed service change the UI reacts to by re-reading one thing (never on a timer), or a
 *  one-off result. Sent as the `ServiceSignal` event, not through `AppView`.
 */
export type ServiceSignal = 
/**  `groups.changed`: re-read the folder groups. */
{ kind: "groups_changed" } | 
/**  `clients.changed` / `http.state`: re-read Connected apps. */
{ kind: "clients_changed" } | 
/**  `activity.added`: re-read the first Activity page. */
{ kind: "activity_added" } | 
/**  `egress.recorded`: re-read the first "Sent to AI providers" page. */
{ kind: "egress_recorded" } | 
/**  `request.progress`: the plain phase line of an Ask / Prompt Enhancer request. */
{ kind: "request_progress"; request_id: string; line: string } | 
/**  `index.move.done`: "Search index moved." */
{ kind: "index_move_done"; path: string } | 
/**  `index.move.failed`: "Nothing was moved. Your index is still in {old path}." */
{ kind: "index_move_failed"; error: UiError; kept_path: string } | 
/**
 *  M5-C `cli_signin.changed`: "Claude (sign in)" / "Codex (sign in)" changed (its sign-in
 *  window closed, a check found a new state). No token, ever.
 */
{ kind: "cli_signin_changed"; status: CliSignInStatus };

export type SettingsSaved = {
	/**  The change re-reads the folder (the UI confirmed it first). */
	reindex: boolean,
	detail: FolderDetailView,
};

export type SkippedPageView = {
	total: number,
	files: SkippedRow[],
};

/**  One skipped file (page 25 table): reasons in plain words; listed files never appear. */
export type SkippedRow = {
	file_id: string,
	rel_path: string,
	reason: string,
	retryable: boolean,
};

export type SourceView = {
	/**  The number used in the text's `[n]` markers. */
	n: number,
	path: string,
	rel_path: string,
	file_name: string,
	folder_name: string,
	line_start: number,
	line_end: number,
};

/**  Pushed whenever the view changes (snapshot, event, re-attach). Never polled. */
export type StateChanged = AppView;

export type SyncMode = "auto" | "manual" | "scheduled" | "triggered";

/**  Search quality tiers in plain words (Basic / Better / Best). */
export type TierName = "basic" | "better" | "best";

export type TierView = {
	active: TierName,
	recommended: TierName,
	/**  Uses the graphics card for indexing. */
	gpu: boolean,
	/**
	 *  The active index uses the multilingual model (snapshot `tier.multilingual`, M4 contract
	 *  Changes 1); `active` then reads `basic`, its resource class. Shown as "Multilingual search".
	 */
	multilingual: boolean,
};

/**  A new tool's password, shown once (OQ-45). */
export type TokenView = {
	client: ServiceClient,
	/**  Setup text with the token filled in: what [Copy] copies. */
	snippet: string,
	/**  The same text with the token shown as `••••` + its last 4 characters (on screen). */
	masked_snippet: string,
	last4: string,
};

/**
 *  The next step offered with an error. Only actions the app can perform are listed; the rest
 *  map to the closest one (documented in `UiError::from`).
 */
export type UiAction = { kind: "none" } | { kind: "retry" } | { kind: "wait_and_retry"; secs: number } | { kind: "choose_folder" } | { kind: "choose_subfolder"; path: string } | { kind: "open_settings" } | { kind: "restart_app" } | { kind: "restart_claude" } | { kind: "copy_diagnostics" } | { kind: "copy_snippet" } | { kind: "free_disk_space" } | 
/**
 *  M3: the provider rejected the key: focus the key field (wizard) or open "Replace key".
 *  `provider` is the display name.
 */
{ kind: "reenter_key"; provider: string } | 
/**  M3: no provider yet: open Providers & Keys. */
{ kind: "add_provider" } | 
/**  M3: `OpenSettings(Providers)` (quota, unknown model): open Providers & Keys. */
{ kind: "open_providers" } | 
/**
 *  M3: code 26 `PrivacyBlocked`: open the consent dialog for this purpose. `provider` is the
 *  display name from the error text; the dialog records the consent for the configured
 *  provider (one provider in v1, OQ-33).
 */
{ kind: "allow_remote"; provider: string; purpose: ConsentPurpose } | 
/**  A pending folder request: bring its card into view. */
{ kind: "review_approval"; id: string } | 
/**
 *  M4 (page 25): open the folder's detail at its "Skipped files" list (codes 9, 12, 13).
 *  `None` = the folder isn't known: the Folders list.
 */
{ kind: "view_skipped_files"; folder_id: string | null } | 
/**  M4: `OpenSettings(Folder)` (code 11): the folder's detail, or the Folders list. */
{ kind: "open_folder"; folder_id: string | null } | 
/**  M4: `OpenSettings(ConnectedApps)`: the Connected apps page (page 29). */
{ kind: "open_connected_apps" };

/**  The one user-facing error shape: title, body, one action, details hidden by default (P1.5). */
export type UiError = {
	title: string,
	body: string,
	action: UiAction,
	/**  Button label for `action` ("" when there is none). */
	action_label: string,
	/**  Shown only under "Details": error code and trace id. Never file contents or secrets. */
	details: string,
};

export type UpdateInfo = {
	version: string,
	notes: string | null,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

